// Renders the two illustrations of the addons.mozilla.org listing (1280x800)
// into store/amo/screenshots/ and copies the first one to docs/demo.png for
// the README. They depict the context menu and a filled form with a company
// generated by the extension code; they are drawings, not browser captures
// (a context menu cannot be captured). The viewer and popup screenshots of
// the listing are real captures, taken by hand (see store/amo/listing.md).
// Usage: npm run store-images
import { copyFileSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';
import { Resvg } from '@resvg/resvg-js';

const rootDir = fileURLToPath(new URL('..', import.meta.url));
const read = (/** @type {string} */ path) => readFileSync(`${rootDir}${path}`, 'utf8');
const icon = read('assets/icon.svg')
  .replace(/<title>[^<]*<\/title>/, '')
  .replace(/<svg[^>]*>/, '')
  .replace('</svg>', '');

const context = vm.createContext({ crypto: globalThis.crypto, structuredClone });
for (const file of [
  'generators/random.js',
  'generators/checksums.js',
  'generators/text.js',
  'generators/company.js',
  'background/data.js',
]) {
  vm.runInContext(read(`extension/${file}`), context);
}
const source = vm
  .runInContext('CffData', context)
  .createSource(async (/** @type {string} */ path) =>
    JSON.parse(read(`extension/data/fr/${path}.json`)),
  );
/** @type {Company} */
const company = await vm.runInContext('CffCompany', context).generate(source);

const FONT = 'Inter, Segoe UI, Arial, sans-serif';
const INDIGO = '#4338CA';
const TEXT = '#1A1E27';

/**
 * @param {string} text
 * @returns {string}
 */
function escape(text) {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

/**
 * @param {number} x
 * @param {number} y
 * @param {string} label
 * @param {string} value
 * @param {{ focused?: boolean }} [options]
 */
function field(x, y, label, value, options = {}) {
  const stroke = options.focused ? INDIGO : '#C9CED8';
  const width = options.focused ? 3 : 1.5;
  return `
    <text x="${x}" y="${y + 33}" font-family="${FONT}" font-size="19" fill="#5A6372">${escape(label)}</text>
    <rect x="${x + 190}" y="${y}" width="440" height="48" rx="3" fill="#fff" stroke="${stroke}" stroke-width="${width}"/>
    <text x="${x + 206}" y="${y + 32}" font-family="${FONT}" font-size="19" fill="${TEXT}">${escape(value)}</text>`;
}

/**
 * @param {string} caption
 * @param {string} content
 */
function frame(caption, content) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="800" viewBox="0 0 1280 800">
  <rect width="1280" height="800" fill="#EEF0FD"/>
  <g transform="translate(64 46) scale(0.42)">${icon}</g>
  <text x="132" y="86" font-family="${FONT}" font-size="29" font-weight="700" fill="${TEXT}">${escape(caption)}</text>
  <rect x="64" y="130" width="1152" height="630" rx="6" fill="#fff" stroke="#DADDE5" stroke-width="2"/>
  <path d="M64 136 a6 6 0 0 1 6 -6 H1210 a6 6 0 0 1 6 6 V180 H64 Z" fill="#F1F2F6"/>
  <circle cx="94" cy="155" r="7" fill="#E5534B"/><circle cx="118" cy="155" r="7" fill="#E8B12E"/><circle cx="142" cy="155" r="7" fill="#3FB86A"/>
  <rect x="180" y="140" width="620" height="30" rx="15" fill="#fff" stroke="#DADDE5"/>
  <text x="200" y="161" font-family="${FONT}" font-size="16" fill="#5A6372">erp.exemple.test/fournisseurs/nouveau</text>
  <text x="110" y="236" font-family="${FONT}" font-size="27" font-weight="700" fill="${TEXT}">Nouveau fournisseur</text>
  ${content}
</svg>`;
}

const ROWS = [
  ['Raison sociale', company.identity.legalName],
  ['Forme juridique', company.identity.legalForm.short],
  ['N° SIRET', company.identity.siret],
  ['N° TVA', company.tax.vatNumber],
  ['Adresse', company.address.line1],
  ['Code postal', company.address.postalCode],
  ['Ville', company.address.city],
  ['IBAN', company.bank.iban.replace(/(.{4})(?=.)/g, '$1 ')],
];

/**
 * @param {boolean} filled
 */
function form(filled) {
  return ROWS.map(([label, value], index) =>
    field(110, 266 + index * 60, label, filled ? value : '', { focused: index === 2 }),
  ).join('');
}

// Context menu opened in the SIRET field, submenu of the extension open.
const menuX = 560;
const menuY = 400;
const nativeItems = ['Annuler', 'Couper', 'Copier', 'Coller', 'Tout sélectionner'];
let menu = `<rect x="${menuX}" y="${menuY}" width="300" height="${nativeItems.length * 36 + 70}" rx="6" fill="#fff" stroke="#C9CED8" stroke-width="1.5"/>`;
nativeItems.forEach((item, index) => {
  menu += `<text x="${menuX + 20}" y="${menuY + 28 + index * 36}" font-family="${FONT}" font-size="18" fill="#3B3E4F">${item}</text>`;
});
const parentY = menuY + nativeItems.length * 36 + 14;
menu += `<line x1="${menuX + 10}" y1="${parentY - 6}" x2="${menuX + 290}" y2="${parentY - 6}" stroke="#E3E5EC" stroke-width="1.5"/>
  <rect x="${menuX + 6}" y="${parentY}" width="288" height="44" rx="4" fill="#E0E7FF"/>
  <g transform="translate(${menuX + 16} ${parentY + 10}) scale(0.19)">${icon}</g>
  <text x="${menuX + 50}" y="${parentY + 29}" font-family="${FONT}" font-size="18" font-weight="600" fill="${TEXT}">Company Form Filler</text>
  <path d="M${menuX + 274} ${parentY + 16} l7 6 l-7 6" fill="none" stroke="${TEXT}" stroke-width="2"/>`;
const subX = menuX + 296;
const subY = parentY - 8;
const subItems = ['Remplir ce champ : SIRET', 'Nouvelle société et remplir'];
menu += `<rect x="${subX}" y="${subY}" width="330" height="${subItems.length * 44 + 12}" rx="6" fill="#fff" stroke="#C9CED8" stroke-width="1.5"/>`;
subItems.forEach((item, index) => {
  const y = subY + 6 + index * 44;
  const active = index === 1;
  if (active) {
    menu += `<rect x="${subX + 6}" y="${y}" width="318" height="44" rx="4" fill="${INDIGO}"/>`;
  }
  menu += `<text x="${subX + 20}" y="${y + 29}" font-family="${FONT}" font-size="18" font-weight="${active ? 600 : 400}" fill="${active ? '#fff' : '#3B3E4F'}">${item}</text>`;
});
menu += `<path d="M${subX + 270} ${subY + 62} l0 26 l7 -6 l6 12 l5 -3 l-6 -11 l9 -1 Z" fill="${TEXT}" stroke="#fff" stroke-width="1.5"/>`;

const first = frame(
  'Clic droit dans un formulaire : une société fictive et cohérente en un clic',
  form(false) + menu,
);

const banner = `<rect x="840" y="690" width="350" height="50" rx="3" fill="#1E1B4B" stroke="#4338CA"/>
  <text x="858" y="722" font-family="${FONT}" font-size="18" fill="#fff">${ROWS.length} champs remplis</text>
  <rect x="1088" y="701" width="88" height="28" rx="2" fill="none" stroke="#A5B4FC"/>
  <text x="1102" y="721" font-family="${FONT}" font-size="16" fill="#fff">Annuler</text>`;
const checks = [2, 3, 7]
  .map((index) => {
    const y = 266 + index * 60 + 24;
    return `<circle cx="770" cy="${y}" r="13" fill="#157F3C"/><path d="M763 ${y} l5 5 l9 -10" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;
  })
  .join('');
const second = frame(
  'SIRET, TVA, IBAN valides, adresse réelle : tout est cohérent',
  form(true) +
    checks +
    `<text x="800" y="420" font-family="${FONT}" font-size="18" fill="#157F3C">Clés de contrôle valides</text>` +
    banner,
);

for (const [name, svg] of [
  ['1-menu.png', first],
  ['2-rempli.png', second],
]) {
  const png = new Resvg(svg, { font: { loadSystemFonts: true } }).render().asPng();
  writeFileSync(`${rootDir}store/amo/screenshots/${name}`, png);
  console.log(`store/amo/screenshots/${name}`);
}

copyFileSync(`${rootDir}store/amo/screenshots/1-menu.png`, `${rootDir}docs/demo.png`);
console.log('docs/demo.png');
